// 🦎 Zig Learning - Step 3: Memory Management - Allocation
// allocation.zig: 메모리 할당 패턴 (스택, 힙, GeneralPurposeAllocator)

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ 스택 할당 (자동 해제)
    stdout.print("=== 1. Stack Allocation ===\n", .{}) catch unreachable;
    var stack_var: i32 = 42;
    stdout.print("stack_var = {}\n", .{stack_var}) catch unreachable;
    // stack_var는 함수가 끝나면 자동으로 해제됨

    // 2️⃣ 배열 스택 할당
    stdout.print("\n=== 2. Array Stack Allocation ===\n", .{}) catch unreachable;
    var arr_stack: [5]i32 = .{1, 2, 3, 4, 5};
    stdout.print("arr_stack[0] = {}, len = {}\n", .{arr_stack[0], arr_stack.len}) catch unreachable;

    // 3️⃣ 힙 할당 - GeneralPurposeAllocator 사용
    stdout.print("\n=== 3. Heap Allocation with GPA ===\n", .{}) catch unreachable;
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer gpa.deinit();
    const allocator = gpa.allocator();

    // 단일 값 할당
    const ptr: *i32 = allocator.create(i32) catch unreachable;
    defer allocator.destroy(ptr);
    ptr.* = 100;
    stdout.print("heap value = {}\n", .{ptr.*}) catch unreachable;

    // 4️⃣ 배열 할당
    stdout.print("\n=== 4. Dynamic Array Allocation ===\n", .{}) catch unreachable;
    var arr_heap = allocator.alloc(i32, 5) catch unreachable;
    defer allocator.free(arr_heap);

    for (0..arr_heap.len) |i| {
        arr_heap[i] = @intCast(i * 10);
    }

    stdout.print("heap array: ", .{}) catch unreachable;
    for (arr_heap) |val| {
        stdout.print("{} ", .{val}) catch unreachable;
    }
    stdout.print("\n", .{}) catch unreachable;

    // 5️⃣ ArrayList (동적 배열)
    stdout.print("\n=== 5. ArrayList (Dynamic Array) ===\n", .{}) catch unreachable;
    var list = std.ArrayList(i32).init(allocator);
    defer list.deinit();

    list.append(10) catch unreachable;
    list.append(20) catch unreachable;
    list.append(30) catch unreachable;

    stdout.print("ArrayList items: ", .{}) catch unreachable;
    for (list.items) |item| {
        stdout.print("{} ", .{item}) catch unreachable;
    }
    stdout.print("\n", .{}) catch unreachable;

    // 6️⃣ 구조체 할당
    stdout.print("\n=== 6. Struct Allocation ===\n", .{}) catch unreachable;
    const Point = struct {
        x: i32,
        y: i32,
    };

    const pt = allocator.create(Point) catch unreachable;
    defer allocator.destroy(pt);
    pt.x = 5;
    pt.y = 10;
    stdout.print("Point: ({}, {})\n", .{pt.x, pt.y}) catch unreachable;

    // 7️⃣ 고정 크기 할당 버퍼 (FixedBufferAllocator)
    stdout.print("\n=== 7. FixedBufferAllocator ===\n", .{}) catch unreachable;
    var fixed_buffer: [256]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&fixed_buffer);
    const fb_allocator = fba.allocator();

    const fixed_arr = fb_allocator.alloc(i32, 3) catch unreachable;
    fixed_arr[0] = 1;
    fixed_arr[1] = 2;
    fixed_arr[2] = 3;
    stdout.print("FixedBuffer array: {any}\n", .{fixed_arr}) catch unreachable;

    // 8️⃣ 메모리 해제 실패 처리
    stdout.print("\n=== 8. Safe Allocation ===\n", .{}) catch unreachable;
    if (allocator.create(i32)) |safe_ptr| {
        defer allocator.destroy(safe_ptr);
        safe_ptr.* = 999;
        stdout.print("Allocated value: {}\n", .{safe_ptr.*}) catch unreachable;
    } else |err| {
        stdout.print("Allocation failed: {}\n", .{err}) catch unreachable;
    }

    stdout.print("\n=== All allocations freed successfully ===\n", .{}) catch unreachable;
}

# Step 3: Memory Management

Zig의 메모리 관리 개념과 포인터, 할당 패턴들을 학습합니다.

## 3.1 메모리 모델 개요

Zig의 메모리는 다음 세 영역으로 나뉩니다:

- **스택(Stack)**: 함수 호출 시 자동으로 할당되고, 함수 종료 시 자동으로 해제되는 메모리
- **힙(Heap)**: 프로그래머가 명시적으로 할당하고 해제해야 하는 메모리
- **전역(Global)**: 프로그램 시작 시 할당되고, 종료 시 해제되는 메모리

```zig
// 스택 할당
var stack_var: i32 = 42;  // 함수 종료 시 자동 해제

// 힙 할당
var allocator = std.heap.GeneralPurposeAllocator(.{}){};
const heap_var = allocator.create(i32) catch unreachable;
allocator.destroy(heap_var);  // 수동 해제 필수
```

## 3.2 포인터 기초

포인터는 메모리 주소를 저장하는 변수입니다.

### 포인터 선언 및 역참조

```zig
var x: i32 = 42;
const ptr: *i32 = &x;  // ptr은 x의 주소를 가리킴
stdout.print("{}\n", .{ptr.*});  // 역참조: ptr이 가리키는 값 출력
```

### 포인터의 종류

| 포인터 타입 | 설명 | 예시 |
|---------|------|------|
| `*T` | 단일 값 포인터 | `*i32`, `*f64` |
| `*[n]T` | 고정 크기 배열 포인터 | `*[5]i32` |
| `*[*]T` | 포인터 배열 | `*[*]u8` |
| `**T` | 이중 포인터 | `**i32` |

## 3.3 포인터와 함수 인자

함수에 포인터를 전달하면, 함수가 호출자의 메모리를 직접 수정할 수 있습니다:

```zig
fn increment(ptr: *i32) void {
    ptr.* += 1;  // ptr이 가리키는 값을 증가
}

pub fn main() void {
    var counter: i32 = 0;
    increment(&counter);  // counter의 주소 전달
    // counter는 이제 1
}
```

이를 통해 함수가 값을 "반환"하지 않고도 수정할 수 있습니다.

## 3.4 const vs var 포인터

Zig에서는 포인터 자체와 포인터가 가리키는 값의 불변성을 구분합니다:

```zig
var y: i32 = 10;
var z: i32 = 20;

// const 포인터: 가리키는 값은 바뀔 수 있지만, 포인터 자체는 변경 불가
const const_ptr: *i32 = &y;
const_ptr.* = 15;  // ✅ OK: 값 변경
// const_ptr = &z;  // ❌ ERROR: 포인터 변경 불가

// var 포인터: 포인터도, 값도 모두 변경 가능
var var_ptr: *i32 = &y;
var_ptr.* = 25;  // ✅ OK: 값 변경
var_ptr = &z;    // ✅ OK: 포인터 변경
```

## 3.5 슬라이스(Slice)

슬라이스는 동적 포인터로, 길이 정보를 포함합니다:

```zig
var arr: [10]i32 = undefined;
const slice: []i32 = &arr;  // 배열에서 슬라이스 생성

stdout.print("slice.len = {}\n", .{slice.len});  // 10
for (slice) |num| {
    stdout.print("{} ", .{num});
}
```

슬라이스는 배열의 일부를 가리킬 수도 있습니다:

```zig
const partial_slice = arr[2..5];  // arr[2], arr[3], arr[4]만 포함
```

## 3.6 메모리 할당: GeneralPurposeAllocator

Zig에서는 명시적으로 할당자(allocator)를 사용합니다:

```zig
var gpa = std.heap.GeneralPurposeAllocator(.{}){};
defer gpa.deinit();
const allocator = gpa.allocator();

// 단일 값 할당
const ptr: *i32 = allocator.create(i32) catch unreachable;
defer allocator.destroy(ptr);
ptr.* = 100;

// 배열 할당
const arr = allocator.alloc(i32, 5) catch unreachable;
defer allocator.free(arr);
arr[0] = 10;
```

**중요**: `defer`를 사용하여 할당 해제를 보장하세요.

## 3.7 ArrayList: 동적 배열

고정 크기를 모를 때 ArrayList를 사용합니다:

```zig
var list = std.ArrayList(i32).init(allocator);
defer list.deinit();

list.append(10) catch unreachable;
list.append(20) catch unreachable;
list.append(30) catch unreachable;

// list.items는 슬라이스
for (list.items) |item| {
    stdout.print("{} ", .{item});
}
```

**내부 동작**:
1. 초기 용량으로 메모리 할당
2. 요소 추가 시 필요하면 용량 자동 증가
3. `deinit()`으로 메모리 해제

## 3.8 다양한 할당자

### FixedBufferAllocator
고정 버퍼에서 할당합니다. 스택 메모리를 힙처럼 사용할 수 있습니다:

```zig
var fixed_buffer: [256]u8 = undefined;
var fba = std.heap.FixedBufferAllocator.init(&fixed_buffer);
const allocator = fba.allocator();

const arr = allocator.alloc(i32, 10) catch unreachable;
// 할당 해제 불필요 (버퍼가 자동으로 정리됨)
```

### PageAllocator
OS 페이지 단위로 할당합니다. 대량의 메모리 필요 시 사용:

```zig
var page_alloc = std.heap.page_allocator;
const large_arr = page_alloc.alloc(u8, 1_000_000) catch unreachable;
defer page_alloc.free(large_arr);
```

## 3.9 메모리 안전성

Zig는 컴파일 타임에 많은 메모리 문제를 방지합니다:

```zig
var x: i32 = 42;
const ptr: *i32 = &x;

// ❌ 컴파일 에러: ptr이 x보다 오래 살아남을 수 없음
// fn get_ptr() *i32 {
//     var local: i32 = 10;
//     return &local;  // local이 함수 종료 시 소멸하므로 불가
// }
```

## 3.10 포인터 비교

두 포인터가 같은 메모리를 가리키는지 확인할 수 있습니다:

```zig
var y: i32 = 10;
var z: i32 = 20;

const ptr_a: *i32 = &y;
const ptr_b: *i32 = &y;
const ptr_c: *i32 = &z;

ptr_a == ptr_b  // true: 같은 메모리 가리킴
ptr_a == ptr_c  // false: 다른 메모리 가리킴
```

## 3.11 구조체와 메모리 할당

구조체도 할당할 수 있습니다:

```zig
const Point = struct {
    x: i32,
    y: i32,
};

const pt = allocator.create(Point) catch unreachable;
defer allocator.destroy(pt);
pt.x = 5;
pt.y = 10;
```

## 3.12 오류 처리와 할당

할당이 실패할 수 있습니다. `catch`로 처리하세요:

```zig
if (allocator.create(i32)) |ptr| {
    defer allocator.destroy(ptr);
    // 할당 성공
} else |err| {
    // 할당 실패 처리
    std.debug.print("Error: {}\n", .{err});
}
```

## 3.13 요약

| 개념 | 특징 | 사용 시기 |
|------|------|----------|
| 스택 할당 | 빠름, 자동 해제 | 크기가 작고 고정적일 때 |
| 포인터 | 메모리 주소 참조 | 함수에서 값 수정할 때 |
| 슬라이스 | 동적 포인터 + 길이 | 배열의 일부 다룰 때 |
| ArrayList | 동적 크기 배열 | 요소 개수가 미리 불명확할 때 |
| GPA | 유연한 할당 | 일반적인 힙 할당 |
| FixedBuffer | 고정 버퍼 사용 | 임베디드/제한된 환경 |

## 3.14 다음 단계

Step 4에서는 **제어 흐름(Control Flow)**을 배웁니다:
- if/else 조건문
- switch/case 케이스
- while/for 루프
- break/continue

