// 🦎 Zig Learning - Step 4: Control Flow - Conditionals
// conditionals.zig: if/else, switch/case 예제

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ 기본 if/else
    stdout.print("=== 1. Basic if/else ===\n", .{}) catch unreachable;
    var x: i32 = 10;

    if (x > 5) {
        stdout.print("x is greater than 5\n", .{}) catch unreachable;
    } else {
        stdout.print("x is 5 or less\n", .{}) catch unreachable;
    }

    // 2️⃣ else if 체인
    stdout.print("\n=== 2. else if Chain ===\n", .{}) catch unreachable;
    var age: i32 = 25;

    if (age < 13) {
        stdout.print("Child\n", .{}) catch unreachable;
    } else if (age < 18) {
        stdout.print("Teenager\n", .{}) catch unreachable;
    } else if (age < 65) {
        stdout.print("Adult\n", .{}) catch unreachable;
    } else {
        stdout.print("Senior\n", .{}) catch unreachable;
    }

    // 3️⃣ 논리 연산자
    stdout.print("\n=== 3. Logical Operators ===\n", .{}) catch unreachable;
    var temp: i32 = 25;
    var humidity: i32 = 60;

    if (temp > 20 and temp < 30) {
        stdout.print("Comfortable temperature\n", .{}) catch unreachable;
    }

    if (humidity < 30 or humidity > 70) {
        stdout.print("Humidity is not ideal\n", .{}) catch unreachable;
    }

    if (!(temp < 0)) {
        stdout.print("It's not freezing\n", .{}) catch unreachable;
    }

    // 4️⃣ 삼항 연산자 (if 표현식)
    stdout.print("\n=== 4. Ternary-like (if expression) ===\n", .{}) catch unreachable;
    var score: i32 = 85;
    const grade = if (score >= 90)
        "A"
    else if (score >= 80)
        "B"
    else if (score >= 70)
        "C"
    else
        "F";

    stdout.print("Grade: {s}\n", .{grade}) catch unreachable;

    // 5️⃣ switch 문
    stdout.print("\n=== 5. Switch Statement ===\n", .{}) catch unreachable;
    var day: i32 = 3;

    switch (day) {
        1 => stdout.print("Monday\n", .{}) catch unreachable,
        2 => stdout.print("Tuesday\n", .{}) catch unreachable,
        3 => stdout.print("Wednesday\n", .{}) catch unreachable,
        4 => stdout.print("Thursday\n", .{}) catch unreachable,
        5 => stdout.print("Friday\n", .{}) catch unreachable,
        6 => stdout.print("Saturday\n", .{}) catch unreachable,
        7 => stdout.print("Sunday\n", .{}) catch unreachable,
        else => stdout.print("Invalid day\n", .{}) catch unreachable,
    }

    // 6️⃣ switch 범위
    stdout.print("\n=== 6. Switch with Ranges ===\n", .{}) catch unreachable;
    var month: i32 = 5;
    const season = switch (month) {
        12, 1, 2 => "Winter",
        3, 4, 5 => "Spring",
        6, 7, 8 => "Summer",
        9, 10, 11 => "Fall",
        else => "Invalid",
    };
    stdout.print("Season: {s}\n", .{season}) catch unreachable;

    // 7️⃣ switch 표현식
    stdout.print("\n=== 7. Switch Expression ===\n", .{}) catch unreachable;
    var code: i32 = 200;
    const status = switch (code) {
        200 => "OK",
        404 => "Not Found",
        500 => "Server Error",
        else => "Unknown",
    };
    stdout.print("HTTP Status: {s}\n", .{status}) catch unreachable;

    // 8️⃣ 중첩된 조건
    stdout.print("\n=== 8. Nested Conditions ===\n", .{}) catch unreachable;
    var user_logged_in: bool = true;
    var is_admin: bool = false;

    if (user_logged_in) {
        if (is_admin) {
            stdout.print("Admin access granted\n", .{}) catch unreachable;
        } else {
            stdout.print("User access granted\n", .{}) catch unreachable;
        }
    } else {
        stdout.print("Please log in\n", .{}) catch unreachable;
    }
}

// 🦎 Zig Learning - Step 4: Control Flow - Loops
// loops.zig: while, for, break, continue 예제

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ while 루프
    stdout.print("=== 1. While Loop ===\n", .{}) catch unreachable;
    var i: i32 = 0;
    while (i < 5) : (i += 1) {
        stdout.print("i = {}\n", .{i}) catch unreachable;
    }

    // 2️⃣ for 루프 (범위)
    stdout.print("\n=== 2. For Loop with Range ===\n", .{}) catch unreachable;
    for (0..5) |j| {
        stdout.print("j = {}\n", .{j}) catch unreachable;
    }

    // 3️⃣ for 루프 (배열)
    stdout.print("\n=== 3. For Loop over Array ===\n", .{}) catch unreachable;
    var numbers: [5]i32 = .{10, 20, 30, 40, 50};
    for (numbers) |num| {
        stdout.print("num = {}\n", .{num}) catch unreachable;
    }

    // 4️⃣ for 루프 (인덱스 포함)
    stdout.print("\n=== 4. For Loop with Index ===\n", .{}) catch unreachable;
    for (numbers, 0..) |num, idx| {
        stdout.print("numbers[{}] = {}\n", .{idx, num}) catch unreachable;
    }

    // 5️⃣ break 문
    stdout.print("\n=== 5. Break Statement ===\n", .{}) catch unreachable;
    var k: i32 = 0;
    while (true) {
        if (k == 3) {
            stdout.print("Breaking at k = {}\n", .{k}) catch unreachable;
            break;
        }
        stdout.print("k = {}\n", .{k}) catch unreachable;
        k += 1;
    }

    // 6️⃣ continue 문
    stdout.print("\n=== 6. Continue Statement ===\n", .{}) catch unreachable;
    for (0..6) |m| {
        if (m == 2 or m == 4) {
            continue;
        }
        stdout.print("m = {}\n", .{m}) catch unreachable;
    }

    // 7️⃣ 중첩 루프
    stdout.print("\n=== 7. Nested Loops ===\n", .{}) catch unreachable;
    for (1..4) |row| {
        for (1..4) |col| {
            stdout.print("({}, {}) ", .{row, col}) catch unreachable;
        }
        stdout.print("\n", .{}) catch unreachable;
    }

    // 8️⃣ 무한 루프 탈출
    stdout.print("\n=== 8. Infinite Loop with Break ===\n", .{}) catch unreachable;
    var counter: i32 = 0;
    while (counter < 100) : (counter += 1) {
        if (counter % 5 == 0) {
            stdout.print("Found multiple of 5: {}\n", .{counter}) catch unreachable;
            break;
        }
    }

    // 9️⃣ do-while 패턴
    stdout.print("\n=== 9. Do-While Pattern ===\n", .{}) catch unreachable;
    var n: i32 = 0;
    while (true) {
        stdout.print("n = {}\n", .{n}) catch unreachable;
        n += 1;
        if (n >= 3) break;
    }

    // 1️⃣0️⃣ 레이블과 break (루프 탈출)
    stdout.print("\n=== 10. Labeled Break ===\n", .{}) catch unreachable;
    outer: for (1..4) |a| {
        for (1..4) |b| {
            if (a == 2 and b == 2) {
                stdout.print("Breaking outer loop at ({}, {})\n", .{a, b}) catch unreachable;
                break :outer;
            }
        }
    }
}

# Step 4: Control Flow

Zig의 조건문과 반복문을 학습합니다.

## 4.1 if/else 조건문

기본 if/else 구조:

```zig
if (condition) {
    // condition이 true일 때 실행
} else {
    // condition이 false일 때 실행
}
```

## 4.2 else if 체인

여러 조건을 순차적으로 확인합니다:

```zig
if (age < 13) {
    stdout.print("Child\n", .{});
} else if (age < 18) {
    stdout.print("Teenager\n", .{});
} else if (age < 65) {
    stdout.print("Adult\n", .{});
} else {
    stdout.print("Senior\n", .{});
}
```

## 4.3 논리 연산자

조건을 조합하려면 `and`, `or`, `!`를 사용합니다:

```zig
if (temp > 20 and temp < 30) {
    // 둘 다 참일 때만
}

if (humidity < 30 or humidity > 70) {
    // 하나라도 참이면
}

if (!(temp < 0)) {
    // not (거짓이면)
}
```

## 4.4 if 표현식 (삼항 연산자 대체)

Zig는 if가 값을 반환할 수 있습니다:

```zig
const grade = if (score >= 90)
    "A"
else if (score >= 80)
    "B"
else
    "F";
```

**주의**: 모든 분기가 같은 타입의 값을 반환해야 합니다.

## 4.5 switch 문

여러 경우를 처리합니다:

```zig
switch (day) {
    1 => stdout.print("Monday\n", .{}),
    2 => stdout.print("Tuesday\n", .{}),
    3 => stdout.print("Wednesday\n", .{}),
    else => stdout.print("Invalid\n", .{}),
}
```

**규칙**:
- 모든 경우를 처리해야 함 (또는 `else` 필수)
- 각 케이스는 정확히 하나의 문장 (또는 블록)
- fall-through 없음 (자동으로 다음 케이스 실행 안 함)

## 4.6 switch 범위와 다중 값

한 케이스에 여러 값이나 범위를 지정할 수 있습니다:

```zig
const season = switch (month) {
    12, 1, 2 => "Winter",      // 여러 값
    3, 4, 5 => "Spring",
    6, 7, 8 => "Summer",
    9, 10, 11 => "Fall",
    else => "Invalid",
};
```

## 4.7 switch 표현식

switch도 값을 반환할 수 있습니다:

```zig
const status = switch (code) {
    200 => "OK",
    404 => "Not Found",
    500 => "Server Error",
    else => "Unknown",
};
```

## 4.8 while 루프

조건이 참인 동안 계속 실행됩니다:

```zig
var i: i32 = 0;
while (i < 5) : (i += 1) {
    stdout.print("i = {}\n", .{i});
}
```

**구조**: `while (condition) : (update) { body }`

- `condition`: 반복 여부 판단
- `update`: 각 반복 후 실행 (선택사항)
- `body`: 반복 본문

## 4.9 for 루프

배열이나 범위에 대해 반복합니다:

```zig
// 범위 반복
for (0..5) |i| {
    stdout.print("i = {}\n", .{i});
}

// 배열 반복
var numbers = .{10, 20, 30, 40, 50};
for (numbers) |num| {
    stdout.print("num = {}\n", .{num});
}

// 인덱스 포함
for (numbers, 0..) |num, idx| {
    stdout.print("numbers[{}] = {}\n", .{idx, num});
}
```

**특징**:
- 범위: `0..n` (0부터 n-1까지, n은 포함 안 함)
- 배열/슬라이스 반복
- 여러 배열 동시 반복 가능

## 4.10 break와 continue

루프를 제어합니다:

```zig
// break: 루프 탈출
while (true) {
    if (k == 3) {
        break;  // 루프 종료
    }
    k += 1;
}

// continue: 다음 반복으로
for (0..6) |m| {
    if (m == 2) {
        continue;  // m == 2일 때 건너뜀
    }
    stdout.print("m = {}\n", .{m});
}
```

## 4.11 레이블과 labeled break

중첩 루프에서 바깥쪽 루프를 탈출할 수 있습니다:

```zig
outer: for (1..4) |a| {
    for (1..4) |b| {
        if (a == 2 and b == 2) {
            break :outer;  // 바깥쪽 루프 탈출
        }
    }
}
```

## 4.12 루프의 일반적인 패턴

### 누적 계산
```zig
var sum: i32 = 0;
for (0..10) |i| {
    sum += i;
}
```

### 조건부 계산
```zig
var count: i32 = 0;
for (numbers) |num| {
    if (num > 50) {
        count += 1;
    }
}
```

### 찾기
```zig
var found: bool = false;
for (numbers) |num| {
    if (num == target) {
        found = true;
        break;
    }
}
```

## 4.13 무한 루프 피하기

```zig
// ❌ 위험: 무한 루프 가능
while (true) {
    // break 없으면 영원히 반복
}

// ✅ 안전: 조건 확인
var i: i32 = 0;
while (i < 10) : (i += 1) {
    // 반드시 종료됨
}
```

## 4.14 중첩 루프

```zig
for (1..4) |row| {
    for (1..4) |col| {
        stdout.print("({}, {}) ", .{row, col});
    }
    stdout.print("\n", .{});
}
```

## 4.15 요약

| 구문 | 용도 | 예시 |
|------|------|------|
| `if/else` | 조건 분기 | `if (x > 0) { ... } else { ... }` |
| `switch` | 다중 선택 | `switch (day) { 1 => "Mon", ... }` |
| `while` | 조건 반복 | `while (i < 10) : (i += 1) { ... }` |
| `for` | 범위/배열 반복 | `for (0..10) \|i\| { ... }` |
| `break` | 루프 탈출 | `break;` |
| `continue` | 다음 반복 | `continue;` |
| `break :label` | 레이블 탈출 | `break :outer;` |

## 4.16 다음 단계

Step 5에서는 **함수와 구조체(Functions & Structs)**를 배웁니다:
- 함수 정의와 호출
- 재귀 함수
- 구조체 정의와 초기화

