// 🦎 Zig Learning - Step 5: Functions & Structs - Functions
// functions.zig: 함수 정의, 매개변수, 반환값, 재귀

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ 기본 함수
    stdout.print("=== 1. Basic Function ===\n", .{}) catch unreachable;
    greet();

    // 2️⃣ 매개변수와 반환값
    stdout.print("\n=== 2. Function with Parameters ===\n", .{}) catch unreachable;
    const sum = add(10, 20);
    stdout.print("add(10, 20) = {}\n", .{sum}) catch unreachable;

    // 3️⃣ 여러 반환값 (다중 반환)
    stdout.print("\n=== 3. Multiple Parameters ===\n", .{}) catch unreachable;
    const product = multiply(5, 6);
    stdout.print("multiply(5, 6) = {}\n", .{product}) catch unreachable;

    // 4️⃣ 부동소수점 함수
    stdout.print("\n=== 4. Float Function ===\n", .{}) catch unreachable;
    const area = circleArea(3.0);
    stdout.print("circleArea(3.0) = {d:.2}\n", .{area}) catch unreachable;

    // 5️⃣ 문자열 반환
    stdout.print("\n=== 5. String Return ===\n", .{}) catch unreachable;
    const status = getStatus(200);
    stdout.print("HTTP 200: {s}\n", .{status}) catch unreachable;

    // 6️⃣ 배열 매개변수
    stdout.print("\n=== 6. Array Parameter ===\n", .{}) catch unreachable;
    var numbers: [5]i32 = .{1, 2, 3, 4, 5};
    const arr_sum = sumArray(&numbers);
    stdout.print("Sum of array: {}\n", .{arr_sum}) catch unreachable;

    // 7️⃣ 조건부 반환
    stdout.print("\n=== 7. Conditional Return ===\n", .{}) catch unreachable;
    const max_val = maxValue(10, 20);
    stdout.print("max(10, 20) = {}\n", .{max_val}) catch unreachable;

    // 8️⃣ 재귀 함수
    stdout.print("\n=== 8. Recursion ===\n", .{}) catch unreachable;
    const factorial = factorial_recursive(5);
    stdout.print("factorial(5) = {}\n", .{factorial}) catch unreachable;

    // 9️⃣ 피보나치 (재귀)
    stdout.print("\n=== 9. Fibonacci ===\n", .{}) catch unreachable;
    stdout.print("fib(8) = {}\n", .{fibonacci(8)}) catch unreachable;

    // 1️⃣0️⃣ 포인터 매개변수
    stdout.print("\n=== 10. Pointer Parameter ===\n", .{}) catch unreachable;
    var value: i32 = 42;
    double(&value);
    stdout.print("After double: {}\n", .{value}) catch unreachable;
}

fn greet() void {
    const stdout = std.io.getStdOut().writer();
    stdout.print("Hello, Zig!\n", .{}) catch unreachable;
}

fn add(a: i32, b: i32) i32 {
    return a + b;
}

fn multiply(a: i32, b: i32) i32 {
    return a * b;
}

fn circleArea(radius: f64) f64 {
    const pi = 3.14159;
    return pi * radius * radius;
}

fn getStatus(code: i32) []const u8 {
    return switch (code) {
        200 => "OK",
        404 => "Not Found",
        500 => "Server Error",
        else => "Unknown",
    };
}

fn sumArray(arr: *[5]i32) i32 {
    var sum: i32 = 0;
    for (arr.*) |num| {
        sum += num;
    }
    return sum;
}

fn maxValue(a: i32, b: i32) i32 {
    if (a > b) {
        return a;
    } else {
        return b;
    }
}

fn factorial_recursive(n: i32) i32 {
    if (n <= 1) {
        return 1;
    } else {
        return n * factorial_recursive(n - 1);
    }
}

fn fibonacci(n: i32) i32 {
    if (n <= 1) {
        return n;
    } else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

fn double(ptr: *i32) void {
    ptr.* *= 2;
}

// 🦎 Zig Learning - Step 5: Functions & Structs - Structs
// structs.zig: 구조체 정의, 초기화, 메서드

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ 기본 구조체
    stdout.print("=== 1. Basic Struct ===\n", .{}) catch unreachable;
    const point1: Point = .{.x = 3, .y = 4};
    stdout.print("Point: ({}, {})\n", .{point1.x, point1.y}) catch unreachable;

    // 2️⃣ 구조체 초기화
    stdout.print("\n=== 2. Struct Initialization ===\n", .{}) catch unreachable;
    var person: Person = .{
        .name = "Alice",
        .age = 30,
    };
    stdout.print("Person: {s}, age {}\n", .{person.name, person.age}) catch unreachable;

    // 3️⃣ 구조체 메서드
    stdout.print("\n=== 3. Struct Methods ===\n", .{}) catch unreachable;
    var person2: Person = .{.name = "Bob", .age = 25};
    person2.haveBirthday();
    stdout.print("After birthday: {}\n", .{person2.age}) catch unreachable;

    // 4️⃣ 구조체 내 메서드 호출
    stdout.print("\n=== 4. Method Chaining ===\n", .{}) catch unreachable;
    const rect = Rectangle{.width = 10, .height = 20};
    const area = rect.getArea();
    const perimeter = rect.getPerimeter();
    stdout.print("Area: {}, Perimeter: {}\n", .{area, perimeter}) catch unreachable;

    // 5️⃣ 중첩 구조체
    stdout.print("\n=== 5. Nested Struct ===\n", .{}) catch unreachable;
    const address: Address = .{
        .street = "Main St",
        .city = "Seoul",
    };
    const person_with_address: PersonWithAddress = .{
        .name = "Charlie",
        .address = address,
    };
    stdout.print("Name: {s}, City: {s}\n", .{person_with_address.name, person_with_address.address.city}) catch unreachable;

    // 6️⃣ 배열의 구조체
    stdout.print("\n=== 6. Array of Structs ===\n", .{}) catch unreachable;
    var people: [3]Person = .{
        .{.name = "Alice", .age = 30},
        .{.name = "Bob", .age = 25},
        .{.name = "Charlie", .age = 35},
    };

    for (people) |p| {
        stdout.print("Person: {s}, age {}\n", .{p.name, p.age}) catch unreachable;
    }

    // 7️⃣ 구조체 포인터
    stdout.print("\n=== 7. Struct Pointer ===\n", .{}) catch unreachable;
    var person3: Person = .{.name = "David", .age = 40};
    const ptr: *Person = &person3;
    ptr.haveBirthday();
    stdout.print("After birthday via pointer: {}\n", .{person3.age}) catch unreachable;

    // 8️⃣ 기본값이 있는 구조체
    stdout.print("\n=== 8. Struct with Defaults ===\n", .{}) catch unreachable;
    const config: Config = .{
        .host = "localhost",
        .port = 3000,
        .debug = true,
    };
    stdout.print("Config: {}:{}, debug={}\n", .{config.host, config.port, config.debug}) catch unreachable;
}

const Point = struct {
    x: i32,
    y: i32,
};

const Person = struct {
    name: []const u8,
    age: i32,

    fn haveBirthday(self: *Person) void {
        self.age += 1;
    }
};

const Rectangle = struct {
    width: i32,
    height: i32,

    fn getArea(self: Rectangle) i32 {
        return self.width * self.height;
    }

    fn getPerimeter(self: Rectangle) i32 {
        return 2 * (self.width + self.height);
    }
};

const Address = struct {
    street: []const u8,
    city: []const u8,
};

const PersonWithAddress = struct {
    name: []const u8,
    address: Address,
};

const Config = struct {
    host: []const u8 = "localhost",
    port: i32 = 8080,
    debug: bool = false,
};

