// 🦎 Zig Learning - Step 6: Error Handling - Error Types
// error-types.zig: error set, try/catch 패턴

const std = @import("std");

// 에러 셋 정의
const FileError = error{
    FileNotFound,
    PermissionDenied,
    IOError,
};

const MathError = error{
    DivisionByZero,
    InvalidInput,
};

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ 기본 에러 반환
    stdout.print("=== 1. Basic Error Return ===\n", .{}) catch unreachable;
    if (divide(10, 2)) |result| {
        stdout.print("10 / 2 = {}\n", .{result}) catch unreachable;
    } else |err| {
        stdout.print("Error: {}\n", .{err}) catch unreachable;
    }

    // 2️⃣ 에러 케이스
    stdout.print("\n=== 2. Error Case ===\n", .{}) catch unreachable;
    if (divide(10, 0)) |result| {
        stdout.print("10 / 0 = {}\n", .{result}) catch unreachable;
    } else |err| {
        stdout.print("Division error: {}\n", .{err}) catch unreachable;
    }

    // 3️⃣ try/catch 패턴
    stdout.print("\n=== 3. Try-Catch Pattern ===\n", .{}) catch unreachable;
    divide_safe(20, 4) catch |err| {
        stdout.print("Error: {}\n", .{err}) catch unreachable;
    };

    // 4️⃣ 파일 작업 시뮬레이션
    stdout.print("\n=== 4. File Operation (Simulated) ===\n", .{}) catch unreachable;
    open_file("data.txt") catch |err| {
        stdout.print("Cannot open file: {}\n", .{err}) catch unreachable;
    };

    // 5️⃣ 여러 에러 타입
    stdout.print("\n=== 5. Multiple Error Types ===\n", .{}) catch unreachable;
    process_data(10) catch |err| {
        stdout.print("Processing error: {}\n", .{err}) catch unreachable;
    };

    // 6️⃣ 에러 전파
    stdout.print("\n=== 6. Error Propagation ===\n", .{}) catch unreachable;
    if (multiply_safe(5, 6)) |result| {
        stdout.print("5 * 6 = {}\n", .{result}) catch unreachable;
    } else |err| {
        stdout.print("Multiplication error: {}\n", .{err}) catch unreachable;
    }

    // 7️⃣ 에러 무시
    stdout.print("\n=== 7. Ignoring Errors ===\n", .{}) catch unreachable;
    const result = divide_safe_ignore(15, 3) catch 0;
    stdout.print("Result (or 0 if error): {}\n", .{result}) catch unreachable;

    // 8️⃣ 기본값 제공
    stdout.print("\n=== 8. Default Value ===\n", .{}) catch unreachable;
    const val = divide(10, 0) catch 0;
    stdout.print("Result with default: {}\n", .{val}) catch unreachable;
}

fn divide(a: i32, b: i32) MathError!i32 {
    if (b == 0) {
        return MathError.DivisionByZero;
    }
    return a / b;
}

fn divide_safe(a: i32, b: i32) !void {
    const result = try divide(a, b);
    const stdout = std.io.getStdOut().writer();
    stdout.print("{} / {} = {}\n", .{a, b, result}) catch unreachable;
}

fn divide_safe_ignore(a: i32, b: i32) !i32 {
    return try divide(a, b);
}

fn open_file(filename: []const u8) FileError!void {
    const stdout = std.io.getStdOut().writer();
    if (std.mem.eql(u8, filename, "secret.txt")) {
        return FileError.PermissionDenied;
    }
    if (!std.mem.eql(u8, filename, "data.txt")) {
        return FileError.FileNotFound;
    }
    stdout.print("Opened: {s}\n", .{filename}) catch unreachable;
}

fn process_data(value: i32) !void {
    if (value < 0) {
        return MathError.InvalidInput;
    }
    const stdout = std.io.getStdOut().writer();
    stdout.print("Processing: {}\n", .{value}) catch unreachable;
}

fn multiply_safe(a: i32, b: i32) !i32 {
    if (a < 0 or b < 0) {
        return MathError.InvalidInput;
    }
    return a * b;
}

// 🦎 Zig Learning - Step 6: Error Handling - Optional Handling
// optional-handling.zig: optional 타입, if-let, orelse 패턴

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ Optional 타입
    stdout.print("=== 1. Optional Type ===\n", .{}) catch unreachable;
    var maybe_number: ?i32 = 42;
    var maybe_none: ?i32 = null;

    stdout.print("maybe_number = {?}\n", .{maybe_number}) catch unreachable;
    stdout.print("maybe_none = {?}\n", .{maybe_none}) catch unreachable;

    // 2️⃣ if-let 패턴 (값 확인)
    stdout.print("\n=== 2. If-Let Pattern ===\n", .{}) catch unreachable;
    if (maybe_number) |value| {
        stdout.print("Found value: {}\n", .{value}) catch unreachable;
    } else {
        stdout.print("No value\n", .{}) catch unreachable;
    }

    if (maybe_none) |value| {
        stdout.print("Found value: {}\n", .{value}) catch unreachable;
    } else {
        stdout.print("No value (none case)\n", .{}) catch unreachable;
    }

    // 3️⃣ orelse 연산자 (기본값)
    stdout.print("\n=== 3. Orelse Operator ===\n", .{}) catch unreachable;
    const value1 = maybe_number orelse 0;
    const value2 = maybe_none orelse 0;

    stdout.print("value1: {}\n", .{value1}) catch unreachable;
    stdout.print("value2: {}\n", .{value2}) catch unreachable;

    // 4️⃣ 함수가 optional 반환
    stdout.print("\n=== 4. Function Returning Optional ===\n", .{}) catch unreachable;
    const result = find_user("Alice");
    if (result) |user| {
        stdout.print("Found: {s}\n", .{user}) catch unreachable;
    } else {
        stdout.print("User not found\n", .{}) catch unreachable;
    }

    // 5️⃣ orelse 체인
    stdout.print("\n=== 5. Chained Orelse ===\n", .{}) catch unreachable;
    var opt1: ?i32 = null;
    var opt2: ?i32 = null;
    var opt3: ?i32 = 99;

    const final = opt1 orelse opt2 orelse opt3 orelse 0;
    stdout.print("Final value: {}\n", .{final}) catch unreachable;

    // 6️⃣ Optional과 포인터
    stdout.print("\n=== 6. Optional Pointer ===\n", .{}) catch unreachable;
    var x: i32 = 42;
    var maybe_ptr: ?*i32 = &x;

    if (maybe_ptr) |ptr| {
        stdout.print("Pointer value: {}\n", .{ptr.*}) catch unreachable;
    }

    // 7️⃣ orelse 블록
    stdout.print("\n=== 7. Orelse Block ===\n", .{}) catch unreachable;
    const username = find_username("unknown") orelse blk: {
        stdout.print("User not found, using default\n", .{}) catch unreachable;
        break :blk "Guest";
    };
    stdout.print("Username: {s}\n", .{username}) catch unreachable;

    // 8️⃣ 배열에서 찾기
    stdout.print("\n=== 8. Finding in Array ===\n", .{}) catch unreachable;
    var numbers: [5]i32 = .{10, 20, 30, 40, 50};
    const found = find_in_array(&numbers, 30);

    if (found) |value| {
        stdout.print("Found: {}\n", .{value}) catch unreachable;
    } else {
        stdout.print("Not found\n", .{}) catch unreachable;
    }
}

fn find_user(name: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, name, "Alice")) {
        return "Alice Smith";
    } else if (std.mem.eql(u8, name, "Bob")) {
        return "Bob Jones";
    }
    return null;
}

fn find_username(name: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, name, "Alice")) {
        return "alice_dev";
    }
    return null;
}

fn find_in_array(arr: *[5]i32, target: i32) ?i32 {
    for (arr.*) |num| {
        if (num == target) {
            return num;
        }
    }
    return null;
}

