// 🦎 Zig Learning - Step 7: Comptime & Generics - Comptime
// comptime.zig: 컴파일타임 계산, @compileError

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ 컴파일타임 상수
    stdout.print("=== 1. Comptime Constant ===\n", .{}) catch unreachable;
    const PI = 3.14159;
    const GREETING: []const u8 = "Hello, Zig!";

    stdout.print("PI = {d}\n", .{PI}) catch unreachable;
    stdout.print("GREETING = {s}\n", .{GREETING}) catch unreachable;

    // 2️⃣ 컴파일타임 계산
    stdout.print("\n=== 2. Comptime Computation ===\n", .{}) catch unreachable;
    const ARRAY_SIZE = 10;
    const SUM = comptime_sum(ARRAY_SIZE);
    stdout.print("Sum of 1..{} = {}\n", .{ARRAY_SIZE, SUM}) catch unreachable;

    // 3️⃣ 컴파일타임 함수
    stdout.print("\n=== 3. Comptime Function ===\n", .{}) catch unreachable;
    const factorial_5 = comptime fibonacci_ct(5);
    stdout.print("comptime fib(5) = {}\n", .{factorial_5}) catch unreachable;

    // 4️⃣ 타입으로서의 컴파일타임
    stdout.print("\n=== 4. Comptime Type ===\n", .{}) catch unreachable;
    const arr_size = 5;
    var arr: [arr_size]i32 = undefined;
    for (0..arr_size) |i| {
        arr[i] = @intCast(i);
    }

    for (arr) |val| {
        stdout.print("{} ", .{val}) catch unreachable;
    }
    stdout.print("\n", .{}) catch unreachable;

    // 5️⃣ @compileError (조건부 에러)
    stdout.print("\n=== 5. @compileError Pattern ===\n", .{}) catch unreachable;
    // 다음은 컴파일 시 에러를 발생시킬 수 있음
    // @compileError("This is intentional");

    // 6️⃣ 조건부 컴파일
    stdout.print("\n=== 6. Conditional Compilation ===\n", .{}) catch unreachable;
    if (comptime std.meta.os == .linux) {
        stdout.print("Compiled for Linux\n", .{}) catch unreachable;
    }

    // 7️⃣ comptime 블록
    stdout.print("\n=== 7. Comptime Block ===\n", .{}) catch unreachable;
    const result = comptime {
        var sum: i32 = 0;
        for (0..10) |i| {
            sum += @intCast(i);
        }
        break :result sum;
    };
    stdout.print("Sum via comptime block: {}\n", .{result}) catch unreachable;

    // 8️⃣ 컴파일타임 배열
    stdout.print("\n=== 8. Comptime Array ===\n", .{}) catch unreachable;
    const squares = comptime generateSquares(5);
    stdout.print("Squares: ", .{}) catch unreachable;
    for (squares) |sq| {
        stdout.print("{} ", .{sq}) catch unreachable;
    }
    stdout.print("\n", .{}) catch unreachable;
}

fn comptime_sum(n: i32) i32 {
    var sum: i32 = 0;
    for (0..n) |i| {
        sum += @intCast(i);
    }
    return sum;
}

fn fibonacci_ct(n: i32) i32 {
    if (n <= 1) return n;
    return fibonacci_ct(n - 1) + fibonacci_ct(n - 2);
}

fn generateSquares(comptime n: i32) [n]i32 {
    var squares: [n]i32 = undefined;
    for (0..n) |i| {
        squares[i] = @intCast(i * i);
    }
    return squares;
}

// 🦎 Zig Learning - Step 7: Comptime & Generics - Generics
// generics.zig: anytype 제너릭 함수, 다형성

const std = @import("std");

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    // 1️⃣ anytype 함수
    stdout.print("=== 1. Anytype Function ===\n", .{}) catch unreachable;
    const sum_ints = add_generic(10, 20);
    stdout.print("add_generic(10, 20) = {}\n", .{sum_ints}) catch unreachable;

    const sum_floats = add_generic(3.5, 2.5);
    stdout.print("add_generic(3.5, 2.5) = {d}\n", .{sum_floats}) catch unreachable;

    // 2️⃣ 제너릭 배열 처리
    stdout.print("\n=== 2. Generic Array ===\n", .{}) catch unreachable;
    var nums: [5]i32 = .{1, 2, 3, 4, 5};
    const len = arrayLength(&nums);
    stdout.print("Array length: {}\n", .{len}) catch unreachable;

    // 3️⃣ 다형성 최대값
    stdout.print("\n=== 3. Polymorphic Max ===\n", .{}) catch unreachable;
    const max_int = max_generic(10, 20);
    const max_float = max_generic(3.14, 2.71);

    stdout.print("max_generic(10, 20) = {}\n", .{max_int}) catch unreachable;
    stdout.print("max_generic(3.14, 2.71) = {d}\n", .{max_float}) catch unreachable;

    // 4️⃣ 제너릭 구조체
    stdout.print("\n=== 4. Generic Struct ===\n", .{}) catch unreachable;
    const box_int: Box(i32) = .{.value = 42};
    const box_str: Box([]const u8) = .{.value = "Hello"};

    stdout.print("Box int: {}\n", .{box_int.value}) catch unreachable;
    stdout.print("Box str: {s}\n", .{box_str.value}) catch unreachable;

    // 5️⃣ 제너릭 배열 합
    stdout.print("\n=== 5. Generic Sum Array ===\n", .{}) catch unreachable;
    var int_arr: [4]i32 = .{1, 2, 3, 4};
    const sum = sumArray(i32, &int_arr);
    stdout.print("Sum of array: {}\n", .{sum}) catch unreachable;

    // 6️⃣ Pair 제너릭
    stdout.print("\n=== 6. Generic Pair ===\n", .{}) catch unreachable;
    const pair: Pair(i32, []const u8) = .{.first = 42, .second = "answer"};
    stdout.print("Pair: ({}, {s})\n", .{pair.first, pair.second}) catch unreachable;

    // 7️⃣ 제너릭 메서드
    stdout.print("\n=== 7. Generic Container ===\n", .{}) catch unreachable;
    const container: Container(f64) = .{.data = 3.14};
    const double = container.double();
    stdout.print("Container double: {d}\n", .{double}) catch unreachable;

    // 8️⃣ 여러 타입 처리
    stdout.print("\n=== 8. Multi-Type Generic ===\n", .{}) catch unreachable;
    const result1 = swap_generic(10, "test");
    stdout.print("Swapped: {d}\n", .{result1.second}) catch unreachable;
}

fn add_generic(a: anytype, b: anytype) @TypeOf(a + b) {
    return a + b;
}

fn max_generic(a: anytype, b: anytype) @TypeOf(a) {
    if (a > b) return a else return b;
}

fn arrayLength(arr: anytype) usize {
    return @typeInfo(@TypeOf(arr)).pointer.child.len;
}

fn sumArray(comptime T: type, arr: []T) T {
    var sum: T = 0;
    for (arr) |val| {
        sum += val;
    }
    return sum;
}

fn Box(comptime T: type) type {
    return struct {
        value: T,
    };
}

fn Pair(comptime A: type, comptime B: type) type {
    return struct {
        first: A,
        second: B,
    };
}

fn Container(comptime T: type) type {
    return struct {
        data: T,

        fn double(self: Container(T)) T {
            return self.data * 2;
        }
    };
}

fn swap_generic(a: anytype, b: anytype) struct {first: @TypeOf(b), second: @TypeOf(a)} {
    return .{.first = b, .second = a};
}

