}

// 공개 구조체
pub const Person = struct {
    name: []const u8,
    age: i32,

    pub fn info(self: Person) void {
        const stdout = std.io.getStdOut().writer();
        stdout.print("{s} is {} years old\n", .{self.name, self.age}) catch unreachable;
    }

    fn private_method(self: Person) void {
