// 🦎 Zig Learning - Step 10: Final Project - Mini Calculator
// mini-calculator.zig: 계산기 구현 (lexer, parser, evaluator)

const std = @import("std");

// 토큰 타입
const TokenType = enum {
    Number,
    Plus,
    Minus,
    Star,
    Slash,
    LParen,
    RParen,
    EOF,
};

const Token = struct {
    type: TokenType,
    value: i32 = 0,
};

// Lexer: 문자열을 토큰으로 분해
const Lexer = struct {
    input: []const u8,
    position: usize = 0,

    fn nextToken(self: *Lexer) Token {
        while (self.position < self.input.len and self.input[self.position] == ' ') {
            self.position += 1;
        }

        if (self.position >= self.input.len) {
            return Token{.type = TokenType.EOF};
        }

        const ch = self.input[self.position];

        if (ch >= '0' and ch <= '9') {
            return self.readNumber();
        }

        self.position += 1;

        return switch (ch) {
            '+' => Token{.type = TokenType.Plus},
            '-' => Token{.type = TokenType.Minus},
            '*' => Token{.type = TokenType.Star},
            '/' => Token{.type = TokenType.Slash},
            '(' => Token{.type = TokenType.LParen},
            ')' => Token{.type = TokenType.RParen},
            else => Token{.type = TokenType.EOF},
        };
    }

    fn readNumber(self: *Lexer) Token {
        var num: i32 = 0;
        while (self.position < self.input.len) {
            const ch = self.input[self.position];
            if (ch >= '0' and ch <= '9') {
                num = num * 10 + (ch - '0');
                self.position += 1;
            } else {
                break;
            }
        }
        return Token{.type = TokenType.Number, .value = num};
    }
};

// Parser: 토큰을 평가
const Parser = struct {
    tokens: []Token,
    position: usize = 0,

    fn parseExpression(self: *Parser) i32 {
        return self.parseTerm();
    }

    fn parseTerm(self: *Parser) i32 {
        var result = self.parseFactor();

        while (self.position < self.tokens.len) {
            const token_type = self.tokens[self.position].type;
            if (token_type == TokenType.Plus or token_type == TokenType.Minus) {
                self.position += 1;
                const right = self.parseFactor();
                if (token_type == TokenType.Plus) {
                    result = result + right;
                } else {
                    result = result - right;
                }
            } else {
                break;
            }
        }

        return result;
    }

    fn parseFactor(self: *Parser) i32 {
        var result = self.parsePrimary();

        while (self.position < self.tokens.len) {
            const token_type = self.tokens[self.position].type;
            if (token_type == TokenType.Star or token_type == TokenType.Slash) {
                self.position += 1;
                const right = self.parsePrimary();
                if (token_type == TokenType.Star) {
                    result = result * right;
                } else {
                    result = result / right;
                }
            } else {
                break;
            }
        }

        return result;
    }

    fn parsePrimary(self: *Parser) i32 {
        if (self.position >= self.tokens.len) {
            return 0;
        }

        const token = self.tokens[self.position];

        if (token.type == TokenType.Number) {
            self.position += 1;
            return token.value;
        } else if (token.type == TokenType.LParen) {
            self.position += 1;
            const result = self.parseExpression();
            self.position += 1;  // skip RParen
            return result;
        } else if (token.type == TokenType.Minus) {
            self.position += 1;
            return -self.parsePrimary();
        }

        return 0;
    }
};

pub fn main() void {
    const stdout = std.io.getStdOut().writer();

    stdout.print("=== Mini Calculator ===\n\n", .{}) catch unreachable;

    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer gpa.deinit();
    const allocator = gpa.allocator();

    // 테스트 표현식들
    const expressions = [_][]const u8{
        "5 + 3",
        "10 - 2",
        "6 * 7",
        "20 / 4",
        "2 + 3 * 4",
        "(2 + 3) * 4",
        "100 / 5 - 4",
        "1 + 2 + 3 + 4",
    };

    for (expressions) |expr| {
        stdout.print("Expression: {s}\n", .{expr}) catch unreachable;

        // 1. Lexer: 문자열을 토큰으로
        var lexer = Lexer{.input = expr};
        var token_list = std.ArrayList(Token).init(allocator);
        defer token_list.deinit();

        while (true) {
            const token = lexer.nextToken();
            token_list.append(token) catch unreachable;
            if (token.type == TokenType.EOF) {
                break;
            }
        }

        // 2. Parser: 토큰을 평가
        var parser = Parser{.tokens = token_list.items};
        const result = parser.parseExpression();

        stdout.print("Result: {}\n\n", .{result}) catch unreachable;
    }

    stdout.print("=== Calculator Tests Complete ===\n", .{}) catch unreachable;
}
